 useEffect(()=>{if(!readyDraft.current||!edit)return;try{localStorage.setItem(draftKey,JSON.stringify({edit,step:visitStep,saved:new Date().toISOString()}));setDraftStatus(navigator.onLine?'Brouillon conservé sur cet appareil':'Hors connexion · brouillon conservé sur cet appareil');}catch{setDraftStatus('Stockage local indisponible : enregistrez le brouillon sur le serveur.')}if(demo||edit.kind!=='visit'||!edit.client_id||!String(edit.data.title||'').trim()||!navigator.onLine)return;const fingerprint=JSON.stringify({data:edit.data,client_id:edit.client_id,project_id:edit.project_id||null,step:visitStep});if(lastServerDraft.current===fingerprint)return;const timer=window.setTimeout(()=>{void(async()=>{try{const saved=await save('visit',{...edit.data,status:'En cours'},edit.record,edit.client_id,edit.project_id,true);lastServerDraft.current=fingerprint;setEdit(current=>current?{...current,record:saved}:current);setDraftStatus('Brouillon enregistré dans le dossier et conservé sur cet appareil.')}catch{setDraftStatus('Enregistrement serveur interrompu : le brouillon reste conservé sur cet appareil.')}})()},1200);return()=>window.clearTimeout(timer)},[edit,visitStep,draftKey,demo]);
 function clearDraft(){try{localStorage.removeItem(draftKey)}catch{}lastServerDraft.current='';setRecovery(null);}
