 async function reload(silent=false){if(demo||reloadRunning.current)return;reloadRunning.current=true;const epoch=writeEpoch.current;if(!silent)setLoading(true);try{const r=await fetch('/api/records',{cache:'no-store'});const data=await r.json();if(!r.ok)throw new Error(data.error);setRecords(current=>reconcileSnapshot(current,data.records,epoch!==writeEpoch.current));setSyncStatus('Synchronisé avec votre entreprise');setUser(previous=>JSON.stringify(previous)===JSON.stringify(data.user)?previous:data.user);setUsers(previous=>JSON.stringify(previous)===JSON.stringify(data.users)?previous:data.users);setMemberships(previous=>JSON.stringify(previous)===JSON.stringify(data.memberships)?previous:data.memberships);setError('');}catch(e){setSyncStatus('Synchronisation interrompue · nouvelle tentative automatique');if(!silent)setError((e as Error).message)}finally{reloadRunning.current=false;if(!silent)setLoading(false)}}
