 useEffect(()=>{document.querySelectorAll<HTMLElement>('.document-detail').forEach(card=>{if(card.dataset.previewReady)return;const link=card.querySelector<HTMLAnchorElement>('a[href*="/api/documents?id="]');if(!link)return;const name=(link.textContent||'').toLowerCase();const url=link.getAttribute('href')||'';let preview:HTMLImageElement|HTMLIFrameElement|null=null;if(/\.(jpe?g|png|webp)$/i.test(name)){preview=document.createElement('img');preview.src=url;preview.alt='Aperçu du document';preview.loading='lazy'}else if(/\.pdf$/i.test(name)){preview=document.createElement('iframe');preview.src=url+'#page=1&view=FitH&toolbar=0';preview.title='Aperçu PDF';preview.tabIndex=-1}else return;preview.className='document-inline-preview';card.prepend(preview);card.dataset.previewReady='true'})},[selected,records]);
 useEffect(()=>{const target=document.querySelector<HTMLElement>('.detail-main .detail-body');if(!target)return;target.querySelectorAll('.direct-document-preview').forEach(node=>node.remove());const documentRecord=records.find(record=>record.id===selected&&record.kind==='document');if(!documentRecord)return;const name=String(documentRecord.data.name||'').toLowerCase();const url='/api/documents?id='+documentRecord.id;const section=document.createElement('section');section.className='direct-document-preview';const heading=document.createElement('h3');heading.textContent='Aperçu';section.append(heading);if(/\.(jpe?g|png|webp)$/i.test(name)||String(documentRecord.data.mime||'').startsWith('image/')){const image=document.createElement('img');image.src=url;image.alt=String(documentRecord.data.caption||documentRecord.data.name||'Photo du dossier');image.loading='eager';image.addEventListener('click',()=>window.open(url,'_blank','noopener'));section.append(image);const note=document.createElement('p');note.textContent='Cliquez sur l’image pour l’ouvrir en grand.';section.append(note)}else if(documentRecord.data.mime==='application/pdf'||/\.pdf$/i.test(name)){const frame=document.createElement('iframe');frame.src=url+'#page=1&view=FitH';frame.title=String(documentRecord.data.name||'Aperçu PDF');section.append(frame)}else{const link=document.createElement('a');link.href=url;link.target='_blank';link.rel='noreferrer';link.textContent='Télécharger le document';section.append(link)}target.prepend(section)},[selected,records]);
