 async function openClientTrash(){if(demo){setTrashedClients(clientTrash(records));setTrashOpen(true);return;}const response=await fetch('/api/records?trash=clients');const result=await response.json();if(!response.ok)throw new Error(result.error||'Corbeille inaccessible.');setTrashedClients(result.records);setTrashOpen(true);}
