 const events=list('visit').filter(visit=>visit.data.date||visit.data.scheduled_at).map(visit=>({id:visit.id,date:String(visit.data.scheduled_at||visit.data.date).slice(0,10),title:String(visit.data.title||'Rendez-vous'),client:clientName(visit.client_id),status:String(visit.data.status||'À planifier'),provider:String(visit.data.assignee||visit.data.provider||'Yello Pro'),color:String(visit.data.calendar_color||'#6e9278'),time:String(visit.data.time||visit.data.start_time||''),project:projectName(visit.project_id)}));
