function Documents(){
 const documents=list('document');
 const [term,setTerm]=useState('');
 const [category,setCategory]=useState('Tous');
 const [order,setOrder]=useState('recent');
 const [preview,setPreview]=useState<RecordItem|null>(null);
 const image=(document:RecordItem)=>String(document.data.mime||'').startsWith('image/');
 const categoryOf=(document:RecordItem)=>String(document.data.category||(/plan|planche|rdc|étage|sous-sol/i.test(String(document.data.name||''))?'Plans':image(document)?'Photos':document.data.mime==='application/pdf'?'PDF':'Autres'));
 const filtered=documents.filter(document=>{const text=`${document.data.name||''} ${document.data.caption||''} ${clientName(document.client_id)}`.toLocaleLowerCase('fr-CA');return (!term||text.includes(term.toLocaleLowerCase('fr-CA')))&&(category==='Tous'||categoryOf(document)===category)}).sort((a,b)=>order==='az'?String(a.data.name||'').localeCompare(String(b.data.name||''),'fr'):order==='old'?a.created_at.localeCompare(b.created_at):b.created_at.localeCompare(a.created_at));
 const selectPreview=(index:number)=>setPreview(filtered[index]||null);
 return <>{(isAdmin||user.role==='worker')&&<FileBrowser projects={list('project')} records={activeRecords(records)} clients={list('client')} canEdit={isAdmin} onOpenRecord={id=>setSelected(id)} onSave={async(document,data)=>{await save('document',data,document,null,null,true)}} onDelete={async document=>{const response=await fetch('/api/documents',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:document.id})});const result=await response.json();if(!response.ok)throw Error(result.error);setRecords(rows=>rows.filter(row=>row.id!==document.id))}}/>}<section className="panel document-library"><div className="panel-title"><div><p className="eyebrow">BIBLIOTHÈQUE DU DOSSIER</p><h2>Documents et photos</h2></div><span>{filtered.length} / {documents.length} fichier(s)</span></div><p className="muted">Les fichiers sont privés et filtrés selon les droits de chaque utilisateur. Ouvrez une carte pour prévisualiser, classer ou partager le document.</p><div className="document-toolbar"><label className="document-search"><Search size={17}/><input value={term} onChange={event=>setTerm(event.target.value)} placeholder="Rechercher un document…" aria-label="Rechercher un document"/></label><label>Tri<select value={order} onChange={event=>setOrder(event.target.value)}><option value="recent">Plus récent</option><option value="old">Plus ancien</option><option value="az">A – Z</option></select></label></div><div className="document-filters" aria-label="Filtrer les documents">{['Tous','Plans','Photos','PDF','Permis','Devis','Factures','Contrats','Technique','Autres'].map(item=><button type="button" key={item} className={category===item?'active':''} onClick={()=>setCategory(item)}>{item}</button>)}</div><div className="document-grid">{filtered.map((document,index)=><button type="button" className={`document-card ${image(document)?'image':''}`} key={document.id} onClick={()=>selectPreview(index)}>{image(document)?<img loading="lazy" src={`/api/documents?id=${document.id}`} alt={document.data.caption||document.data.name||'Photo du projet'}/>:document.data.mime==='application/pdf'?<iframe loading="lazy" title={`Aperçu ${document.data.name||'PDF'}`} src={`/api/documents?id=${document.id}#page=1&view=FitH&toolbar=0`} tabIndex={-1}/>:<div className="document-card-icon"><FileText size={27}/><span>Document</span></div>}<div className="document-card-copy"><b>{document.data.name}</b><small>{categoryOf(document)} · {clientName(document.client_id)}</small><small>{document.data.visibility==='client'?'Partagé avec le client':'Interne'} · {new Intl.DateTimeFormat('fr-CA',{day:'numeric',month:'short',year:'numeric'}).format(new Date(document.created_at))}</small></div><Eye size={17}/></button>)}</div>{!filtered.length&&<Empty text={documents.length?'Aucun document ne correspond à ces filtres.':'Les plans, photos et documents de vos dossiers seront réunis ici.'}/>}</section>{preview&&<Modal title={preview.data.name||'Document'} close={()=>setPreview(null)} wide><div className="document-preview">{image(preview)?<img src={`/api/documents?id=${preview.id}`} alt={preview.data.caption||preview.data.name||'Aperçu du document'}/>:preview.data.mime==='application/pdf'?<iframe title={preview.data.name||'PDF'} src={`/api/documents?id=${preview.id}#view=FitH`}/>:<a className="btn secondary" href={`/api/documents?id=${preview.id}`} target="_blank" rel="noreferrer"><Download size={16}/>Télécharger le document</a>}</div><div className="document-preview-actions"><a className="btn secondary" href={`/api/documents?id=${preview.id}`} target="_blank" rel="noreferrer"><Download size={16}/>Télécharger</a><button type="button" className="btn secondary" disabled={filtered.length<2} onClick={()=>{const at=filtered.findIndex(document=>document.id===preview.id);selectPreview((at-1+filtered.length)%filtered.length)}}>Précédent</button><button type="button" className="btn secondary" disabled={filtered.length<2} onClick={()=>{const at=filtered.findIndex(document=>document.id===preview.id);selectPreview((at+1)%filtered.length)}}>Suivant</button></div>{isAdmin&&<form className="document-metadata" onSubmit={event=>{event.preventDefault();const form=new FormData(event.currentTarget);run(async()=>{const saved=await save('document',{...preview.data,name:String(form.get('name')||'').trim().slice(0,180),category:String(form.get('category')||'Autres'),visibility:String(form.get('visibility')||'internal')},preview);setPreview(saved);notify('Document mis à jour.');})}}><label>Nom<input name="name" required defaultValue={preview.data.name||''}/></label><label>Catégorie<select name="category" defaultValue={categoryOf(preview)}>{['Plans','Photos','PDF','Permis','Devis','Factures','Contrats','Administratif','Technique','Autres'].map(item=><option key={item}>{item}</option>)}</select></label><label>Accès<select name="visibility" defaultValue={preview.data.visibility||'internal'}><option value="internal">Interne</option><option value="client">Visible par le client</option></select></label><button className="btn primary" disabled={busy}><Save size={16}/>Enregistrer</button><button type="button" className="btn danger" disabled={busy} onClick={()=>{if(!confirm(`Supprimer « ${preview.data.name||'ce document'} » ?`))return;run(async()=>{const response=await fetch('/api/documents',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:preview.id})});const result=await response.json();if(!response.ok)throw Error(result.error);setRecords(rows=>rows.filter(row=>row.id!==preview.id));setPreview(null);notify(result.warning||'Document supprimé.');})}}><Trash2 size={16}/>Supprimer</button></form>}</Modal>}</>}
